test "t02 gcd y lcm" {
    try std.testing.expectEqual(@as(u64, 6), gcd(12, 18));
    try std.testing.expectEqual(@as(u64, 5), gcd(0, 5));
    try std.testing.expectEqual(@as(u64, 0), gcd(0, 0));
    try std.testing.expectEqual(@as(u64, 12), lcm(4, 6));
    try std.testing.expectEqual(@as(u64, 42), lcm(21, 6));
    try std.testing.expectEqual(@as(u64, 0), lcm(0, 7));
}
